import time

def ask_with_retry(call, tries=4):
    delay = 1
    for attempt in range(tries):
        try:
            return call()
        except TimeoutError:
            if attempt == tries - 1:
                raise
            time.sleep(delay)
            delay *= 2         # 1s, 2s, 4s ...

