def allowed(meta, user_level):
    order = {"public": 0, "staff": 1, "admin": 2}
    return order[meta.get("access", "public")] <= order[user_level]

def secure_search(q, user_level, k=5):
    hits = search(q, k * 3)               # over-fetch, then filter
    return [(t, m) for t, m in hits if allowed(m, user_level)][:k]

