import re, time
from collections import defaultdict

calls = defaultdict(list)
def rate_limited(user_id, limit=20, window=60):
    now = time.time()
    calls[user_id] = [t for t in calls[user_id] if now - t < window]
    if len(calls[user_id]) >= limit:
        return True
    calls[user_id].append(now)
    return False

SECRET = re.compile(r"(sk-[A-Za-z0-9]{10,}|\b\d{8,}\b)")
def clean_output(text):
    return SECRET.sub("[removed]", text)

